var builder = WebApplication.CreateBuilder(args);

builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new OpenApiInfo { Title = "My API", Version = "v1" });
});

var app = builder.Build();

if (app.Environment.IsDevelopment())
{
    app.UseSwagger(options =>
    {
        options.PreSerializeFilters.Add((swaggerDoc, httpReq) =>
        {
            swaggerDoc.Servers = new List<OpenApiServer>
            {
                new OpenApiServer { Url = $"{httpReq.Scheme}://{httpReq.Host.Value}" }
            };
        });
    });
    app.UseSwaggerUI(c =>
    {
        c.SwaggerEndpoint("/swagger/v1/swagger.yaml", "My API V1 (YAML)");
    });
}

app.MapGet("/weather", () => Results.Json(new { temp = 25 }))
   .WithName("GetWeather")
   .WithOpenApi();

app.MapGet("/generate-openapi-yaml", (ISwaggerProvider swaggerProvider) =>
{
    var doc = swaggerProvider.GetSwagger("v1");
    var yaml = new OpenApiYamlWriter();
    using var writer = new StringWriter();
    yaml.Write(doc, writer);
    return Results.Text(writer.ToString(), "application/x-yaml");
})
